src='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p); q.append(p)
            y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
            x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
            # A component with an enclosed zero belongs at the top; other shapes belong at the bottom.
            box = {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)}
            occupied = set(cells)
            outside = set()
            q0 = []
            for y in range(y0,y1+1):
                for x in (x0,x1):
                    if (y,x) not in occupied and (y,x) not in outside: outside.add((y,x)); q0.append((y,x))
            for x in range(x0,x1+1):
                for y in (y0,y1):
                    if (y,x) not in occupied and (y,x) not in outside: outside.add((y,x)); q0.append((y,x))
            while q0:
                y,x=q0.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if y0<=p[0]<=y1 and x0<=p[1]<=x1 and p not in occupied and p not in outside:
                        outside.add(p); q0.append(p)
            closed = any(p not in occupied and p not in outside for p in box)
            objs.append(dict(cells=cells, color=color, y0=y0,x0=x0,height=y1-y0+1,width=x1-x0+1,closed=closed))
    placed=[]
    # Preserve the input vertical order while packing each class against its destination edge.
    for closed in (True, False):
        group=[o for o in objs if o['closed']==closed]
        group.sort(key=lambda o: (o['y0'],o['x0']))
        if not closed: group.reverse()
        for o in group:
            if closed:
                candidates=range(0, h-o['height']+1)
            else:
                candidates=range(h-o['height'], -1, -1)
            for y in candidates:
                rect=(y,y+o['height']-1,o['x0'],o['x0']+o['width']-1)
                if all(rect[1]<p[0] or p[1]<rect[0] or rect[3]<p[2] or p[3]<rect[2] for p in placed):
                    break
            placed.append(rect)
            dy=y-o['y0']
            o['dy']=dy
    out=[[0]*w for _ in range(h)]
    for o in objs:
        for y,x in o['cells']:
            out[y+o['dy']][x]=o['color']
    return out
